import { test } from "node:test";
import { capitalize, slugify } from "../src/text.ts";

test("grader: slugify", () => {
  assert.equal(slugify("Hello, World!"), "hello-world");
  assert.equal(slugify("  Many   spaces "), "many-spaces");
  assert.equal(slugify("Ünïcode café"), "unicode-cafe");
  assert.equal(slugify("--a--"), "a");
  assert.equal(slugify(""), "");
  assert.equal(capitalize("x"), "X");
});

